import asyncio
import socket
from typing import List
from .base import ScannerPlugin, Finding, Severity

class PortScannerPlugin(ScannerPlugin):
    """
    Performs asynchronous TCP port scanning to identify open services.
    """
    @property
    def plugin_id(self) -> str:
        return "NET_RECON_01"

    async def run(self, target: str) -> List[Finding]:
        findings = []
        # Default ports to scan if not specified in config
        ports = self.config.get("ports", [21, 22, 23, 25, 53, 80, 443, 8080, 8443])
        
        for port in ports:
            if await self._check_port(target, port):
                findings.append(Finding(
                    plugin_id=self.plugin_id,
                    severity=Severity.INFO,
                    title=f"Open Port Detected: {port}",
                    description=f"TCP Port {port} is open on the target system.",
                    evidence=f"{target}:{port}",
                    remediation="Close unused ports or restrict access via firewall."
                ))
        return findings

    async def _check_port(self, target: str, port: int) -> bool:
        try:
            # Use asyncio.open_connection for non-blocking socket checks
            conn = asyncio.open_connection(target, port)
            _, writer = await asyncio.wait_for(conn, timeout=self.config.get("timeout", 1.0))
            writer.close()
            await writer.wait_closed()
            return True
        except (asyncio.TimeoutError, ConnectionRefusedError, OSError):
            return False